-- Milestone 5a: security review (ADR-0005).
-- Part 1 is generated by Prisma from schema.prisma. Part 2 (security) is hand-written.
-- Runs as kenisha_migrator with search_path = kenisha. One transaction; ASCII only.

BEGIN;

-- ===========================================================================
-- Part 1: tables (generated)
-- ===========================================================================

-- CreateTable
CREATE TABLE "known_devices" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "tenant_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "device_hash" CHAR(64) NOT NULL,
    "first_seen_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "last_seen_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "known_devices_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "known_devices_tenant_id_user_id_device_hash_key" ON "known_devices"("tenant_id", "user_id", "device_hash");

-- AddForeignKey
ALTER TABLE "known_devices" ADD CONSTRAINT "known_devices_tenant_id_user_id_fkey" FOREIGN KEY ("tenant_id", "user_id") REFERENCES "users"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- ===========================================================================
-- Part 2: security (hand-written)
-- ===========================================================================

ALTER TABLE "known_devices" ADD CONSTRAINT "known_devices_hash_hex"
  CHECK ("device_hash" ~ '^[0-9a-f]{64}$');

-- known_devices: hospital role; no DELETE (old rows are purged below) -------------------
ALTER TABLE "known_devices" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "known_devices" FORCE ROW LEVEL SECURITY;
GRANT SELECT, INSERT ON "known_devices" TO kenisha_app;
GRANT UPDATE ("last_seen_at") ON "known_devices" TO kenisha_app;
CREATE POLICY "known_devices_tenant_isolation" ON "known_devices" TO kenisha_app
  USING ("tenant_id" = (SELECT "current_tenant_id"()))
  WITH CHECK ("tenant_id" = (SELECT "current_tenant_id"()));

-- Data minimisation: purge expired authentication data ---------------------------------
-- purge_expired_auth_data() runs as the schema owner. Under FORCE RLS the owner needs
-- policies; each one admits ONLY rows that are already past retention, so even this
-- function cannot read or delete live codes, sessions, invitations or devices.
-- Audit events are never purged here (retention to be set with legal counsel).
--   one-time codes          1 day after expiry
--   sessions                90 days after revocation or expiry (kept for investigations)
--   invitations             90 days after acceptance, revocation or expiry
--   known devices           365 days after last use

CREATE POLICY "otp_challenges_owner_purge_read" ON "otp_challenges" FOR SELECT
  TO kenisha_migrator USING ("expires_at" < now() - interval '1 day');
CREATE POLICY "otp_challenges_owner_purge" ON "otp_challenges" FOR DELETE
  TO kenisha_migrator USING ("expires_at" < now() - interval '1 day');

CREATE POLICY "sessions_owner_purge_read" ON "sessions" FOR SELECT TO kenisha_migrator
  USING ("revoked_at" < now() - interval '90 days'
         OR "expires_at" < now() - interval '90 days'
         OR "absolute_expires_at" < now() - interval '90 days');
CREATE POLICY "sessions_owner_purge" ON "sessions" FOR DELETE TO kenisha_migrator
  USING ("revoked_at" < now() - interval '90 days'
         OR "expires_at" < now() - interval '90 days'
         OR "absolute_expires_at" < now() - interval '90 days');

CREATE POLICY "platform_sessions_owner_purge_read" ON "platform_sessions" FOR SELECT
  TO kenisha_migrator
  USING ("revoked_at" < now() - interval '90 days' OR "expires_at" < now() - interval '90 days');
CREATE POLICY "platform_sessions_owner_purge" ON "platform_sessions" FOR DELETE
  TO kenisha_migrator
  USING ("revoked_at" < now() - interval '90 days' OR "expires_at" < now() - interval '90 days');

-- staff_invitations already has an unrestricted owner SELECT policy (tenant_usage).
CREATE POLICY "staff_invitations_owner_purge" ON "staff_invitations" FOR DELETE
  TO kenisha_migrator
  USING (("status" <> 'PENDING' AND "updated_at" < now() - interval '90 days')
         OR ("status" = 'PENDING' AND "expires_at" < now() - interval '90 days'));

CREATE POLICY "known_devices_owner_purge_read" ON "known_devices" FOR SELECT
  TO kenisha_migrator USING ("last_seen_at" < now() - interval '365 days');
CREATE POLICY "known_devices_owner_purge" ON "known_devices" FOR DELETE
  TO kenisha_migrator USING ("last_seen_at" < now() - interval '365 days');

CREATE FUNCTION "purge_expired_auth_data"()
  RETURNS TABLE (otp_challenges integer, sessions integer, platform_sessions integer,
                 staff_invitations integer, known_devices integer)
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
  AS $$
  DECLARE
    n_otp integer; n_sessions integer; n_platform integer; n_invitations integer; n_devices integer;
  BEGIN
    -- The WHERE clauses repeat the owner policies; the policies are the enforcement.
    DELETE FROM kenisha.otp_challenges WHERE expires_at < now() - interval '1 day';
    GET DIAGNOSTICS n_otp = ROW_COUNT;
    DELETE FROM kenisha.sessions
      WHERE revoked_at < now() - interval '90 days'
         OR expires_at < now() - interval '90 days'
         OR absolute_expires_at < now() - interval '90 days';
    GET DIAGNOSTICS n_sessions = ROW_COUNT;
    DELETE FROM kenisha.platform_sessions
      WHERE revoked_at < now() - interval '90 days' OR expires_at < now() - interval '90 days';
    GET DIAGNOSTICS n_platform = ROW_COUNT;
    DELETE FROM kenisha.staff_invitations
      WHERE (status <> 'PENDING' AND updated_at < now() - interval '90 days')
         OR (status = 'PENDING' AND expires_at < now() - interval '90 days');
    GET DIAGNOSTICS n_invitations = ROW_COUNT;
    DELETE FROM kenisha.known_devices WHERE last_seen_at < now() - interval '365 days';
    GET DIAGNOSTICS n_devices = ROW_COUNT;
    RETURN QUERY SELECT n_otp, n_sessions, n_platform, n_invitations, n_devices;
  END
  $$;
REVOKE ALL ON FUNCTION "purge_expired_auth_data"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "purge_expired_auth_data"() TO kenisha_app;

COMMIT;
